@import "tailwindcss";
@import "tw-animate-css";

@custom-variant dark (&:is(.dark *));

/* ─────────────────────────────────────────────
   MASJID ERP — Design System Tokens (OKLCH)
   Palette: Emerald · Teal · Warm Slate (Dark)
   Harmonized from Landing Page visual identity
───────────────────────────────────────────── */
@theme inline {
  --radius-sm: calc(var(--radius) * 0.6);
  --radius-md: calc(var(--radius) * 0.8);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) * 1.4);
  --radius-2xl: calc(var(--radius) * 1.8);
  --radius-3xl: calc(var(--radius) * 2.2);
  --radius-4xl: calc(var(--radius) * 2.6);

  /* Core Color Mappings */
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-success: var(--success);
  --color-warning: var(--warning);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);

  /* Chart Colors */
  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);

  /* Sidebar Colors */
  --color-sidebar: var(--sidebar);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-ring: var(--sidebar-ring);

  /* ── Extended Brand Tokens ──────────────────
     Use these for manual accent overrides:
     bg-[var(--emerald-glow)]  /  text-[var(--teal)]
  ─────────────────────────────────────────── */
  --color-emerald-glow: var(--emerald-glow);
  --color-teal: var(--teal);
  --color-amber-accent: var(--amber-accent);
  --color-blue-accent: var(--blue-accent);
}

/* ╔══════════════════════════════════════════════╗
   ║           LIGHT MODE  ( :root )              ║
   ╚══════════════════════════════════════════════╝
   Brand story:
   • Background  → warm near-white with faint green hue (airy, clean)
   • Card        → pure white (crisp panels)
   • Primary     → Emerald 500 (oklch ≈ 0.696 0.17 162) — the brand hero
   • Accent      → Teal tint (softer, secondary interactables)
   • Muted       → cool light-green-grey surfaces & disabled text
   • Foreground  → deep warm-slate for max readability
*/
:root {
  --radius: 0.75rem;

  /* Surfaces */
  --background: oklch(0.985 0.008 165); /* warm off-white, faint emerald tint */
  --foreground: oklch(0.22 0.025 195); /* deep slate-green — very readable    */
  --card: oklch(1 0 0); /* pure white cards                    */
  --card-foreground: oklch(0.22 0.025 195);

  /* Popovers */
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.22 0.025 195);

  /* ── Primary: Emerald 500 ──
     Used for: buttons,active tabs, progress bars, CTAs, logo accent
     Tailwind classes: bg-primary  text-primary  border-primary  ring-primary
  */
  --primary: oklch(0.696 0.17 162); /* Emerald 500 */
  --primary-foreground: oklch(1 0 0); /* white text on emerald */

  /* ── Secondary: Muted Teal-Green──
     Used for: secondary buttons, ghost states, subtle surfaces
     Tailwind: bg-secondary  text-secondary-foreground
  */
  --secondary: oklch(0.935 0.03 162); /* faint emerald wash */
  --secondary-foreground: oklch(0.35 0.06 162); /* mid emerald text  */

  /* ── Muted: Greyed backgrounds + helper text ──
     Used for: nav bg, table rows alt, code blocks, disabled
     Tailwind: bg-muted  text-muted-foreground
  */
  --muted: oklch(0.94 0.015 165);
  --muted-foreground: oklch(0.52 0.025 175);

  /* ── Accent: Soft Teal ──
     Used for: hover highlights, badges bg, notification dots
     Tailwind: bg-accent  text-accent-foreground
  */
  --accent: oklch(0.91 0.05 175); /* teal-tinged light surface */
  --accent-foreground: oklch(0.3 0.07 175); /* dark teal text            */

  /* ── Semantic ── */
  --destructive: oklch(0.580.2 25); /* red-orange             */
  --success: oklch(0.696 0.17 162); /* same as primary: emerald */
  --warning: oklch(0.75 0.14 75); /* amber                  */

  /* ── Borders & Inputs ── */
  --border: oklch(0.88 0.02 165);
  --input: oklch(0.94 0.015 165);
  --ring: oklch(0.696 0.17 162); /* emerald focus ring */

  /* ── Charts ──
     Tuned to look natural alongside emerald primary
  */
  --chart-1: oklch(0.696 0.17 162); /* emerald — primary series      */
  --chart-2: oklch(0.65 0.13 195); /* teal-blue — secondary series  */
  --chart-3: oklch(0.75 0.14 75); /* amber                         */
  --chart-4: oklch(0.6 0.15 255); /* indigo/blue                   */
  --chart-5: oklch(0.65 0.18 25); /* warm coral                    */

  /* ── Sidebar ── */
  --sidebar: oklch(0.975 0.01 165);
  --sidebar-foreground: oklch(0.28 0.025 195);
  --sidebar-primary: oklch(0.696 0.17 162);
  --sidebar-primary-foreground: oklch(1 0 0);
  --sidebar-accent: oklch(0.91 0.05 175);
  --sidebar-accent-foreground: oklch(0.3 0.07 175);
  --sidebar-border: oklch(0.88 0.02 165);
  --sidebar-ring: oklch(0.696 0.17 162);

/* ── Extended Brand Tokens ── */
  --emerald-glow: oklch(
    0.696 0.17 162 / 0.15
  ); /* transparent emerald for glow divs */
  --teal:oklch(0.66 0.14 190);
  --amber-accent: oklch(0.75 0.14 75);
  --blue-accent: oklch(0.6 0.15 255);
}

/* ╔══════════════════════════════════════════════╗
   ║           DARK MODE  ( .dark )               ║
   ╚══════════════════════════════════════════════╝
   Brand story:
• Background  → very deep warm-slate (not pure black — warmer, premium)
   • Card        → slightly elevated dark surface
   • Primary     → Emerald 400-ish (lighter for contrast on dark)
   • Accent      → dark teal tint
   • Muted       → subtle dark surfaces and softer helper text
*/
.dark {
  /* Surfaces */
  --background: oklch(0.165 0.018 210); /* deep warm-slate, near-black     */
  --foreground: oklch(0.93 0.012 180); /* soft warm-white, easy on eyes   */
  --card: oklch(0.205 0.02 205); /* slightly lifted dark panel      */
  --card-foreground: oklch(0.93 0.012 180);

  /* Popovers */
  --popover: oklch(0.205 0.02 205);
  --popover-foreground: oklch(0.93 0.012 180);

  /* ── Primary: Emerald 400 (lighter for dark bg) ──
     Lightened so it pops on dark surfaces with WCAG AA contrast
  */
  --primary: oklch(0.76 0.16 162); /* Emerald ~400 on dark          */
  --primary-foreground: oklch(
    0.12 0.02 195
  ); /* very dark text on bright btn  */

  /* ── Secondary── */
  --secondary: oklch(0.265 0.03 175); /* dark teal-green surface        */
  --secondary-foreground: oklch(
    0.88 0.03 165
  ); /*light green text on secondary  */

  /* ── Muted ── */
  --muted: oklch(0.248 0.022 200);
  --muted-foreground: oklch(0.58 0.025 180);

  /* ── Accent: Dark Teal Wash ── */
  --accent: oklch(0.265 0.04 175);
  --accent-foreground: oklch(0.88 0.05 165);

  /* ── Semantic ──*/
  --destructive: oklch(0.65 0.2 25);
  --success: oklch(0.76 0.16 162);
  --warning: oklch(0.8 0.14 75);

  /* ── Borders & Inputs ──*/
  --border: oklch(0.3 0.025 200);
  --input: oklch(0.248 0.022 200);
  --ring: oklch(0.76 0.16 162); /* emerald ring in dark           */

  /* ── Charts ── */
  --chart-1: oklch(0.76 0.16 162); /* emerald — primary        */
  --chart-2: oklch(0.7 0.12 195); /* teal-blue        */
  --chart-3: oklch(0.8 0.14 75); /* amber                    */
  --chart-4: oklch(0.65 0.15 255); /* indigo                   */
--chart-5: oklch(0.68 0.18 25); /* coral                    */

  /* ── Sidebar ── */
  --sidebar: oklch(0.14 0.018 210);
  --sidebar-foreground: oklch(0.82 0.015 180);
  --sidebar-primary: oklch(0.76 0.16 162);
  --sidebar-primary-foreground: oklch(0.12 0.02 195);
  --sidebar-accent: oklch(0.248 0.03 175);
  --sidebar-accent-foreground: oklch(0.82 0.03 165);
  --sidebar-border: oklch(0.265 0.022 205);
  --sidebar-ring: oklch(0.76 0.16 162);

  /* ── Extended Brand Tokens ── */
  --emerald-glow: oklch(0.76 0.16 162 / 0.12);
  --teal: oklch(0.7 0.13 190);
--amber-accent: oklch(0.8 0.14 75);
  --blue-accent: oklch(0.65 0.15 255);
}

/* ─────────────────────────────────────────────
   BASE RESET & RTL DEFAULTS
───────────────────────────────────────────── */
*,
*::before,
*::after {
  box-sizing: border-box;
  border-color: var(--border);
}

html {
  scroll-behavior: smooth;
  text-size-adjust: 100%;
  -webkit-text-size-adjust: 100%;
}

body {
  background-color: var(--background);
  color: var(--foreground);
  font-feature-settings:
    "kern" 1,
    "liga" 1,
    "calt" 1;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  min-height: 100dvh;
}

/* RTL typography fine-tuning */
[dir="rtl"] {
  text-align: right;
}

/* ─────────────────────────────────────────────
   SCROLLBAR STYLING
───────────────────────────────────────────── */
::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}
::-webkit-scrollbar-track {
  background: transparent;
}
::-webkit-scrollbar-thumb {
  background: var(--muted-foreground);
  border-radius: 99px;
  opacity: 0.4;
}
::-webkit-scrollbar-thumb:hover {
  background: var(--primary);
}

/* ─────────────────────────────────────────────
   UTILITY: Noise Texture Overlay
   Usage: add className="bg-noise" to any element
───────────────────────────────────────────── */
@layer utilities {
  .bg-noise {
    position: relative;
    isolation: isolate;
  }
  .bg-noise::after {
    content: "";
    position: absolute;
    inset: 0;
    z-index: -1;
    pointer-events: none;
    border-radius: inherit;
    opacity: 0.025;
    background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noise'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noise)' opacity='1'/%3E%3C/svg%3E");
    background-repeat: repeat;
    background-size: 128px 128px;
  }

  /* Sidebar active gradient glow */
  .sidebar-active-glow {
    background: linear-gradient(
      135deg,
      oklch(from var(--primary) l c h / 0.15),
      oklch(from var(--primary) l c h / 0.05)
    );
    box-shadow: inset 2px 0 0 var(--primary);
  }

  /* Glass card effect */
  .glass-card {
    background: oklch(from var(--card) l c h / 0.8);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border: 1px solid oklch(from var(--border) l c h / 0.6);
  }

  /* Subtle gradient shimmer for nav items on hover */

  /* Focus ring RTL-aware */
  .focus-ring {
    outline: 2px solid transparent;
    outline-offset: 2px;
  }
  .focus-ring:focus-visible {
    outline-color: var(--ring);
  }

  /* ── Emerald glow helper (replaces raw emerald-500/10 divs) ── */
}

/* ─────────────────────────────────────────────
   ANIMATION KEYFRAMES
───────────────────────────────────────────── */
@keyframes slide-in-right {
  from {
    transform: translateX(100%);
    opacity: 0;
  }
  to {
    transform: translateX(0);
    opacity: 1;
  }
}

@keyframes slide-in-left {
  from {
    transform: translateX(-100%);
    opacity: 0;
  }
  to {
    transform: translateX(0);
    opacity: 1;
  }
}

@keyframes fade-up {
  from {
    transform: translateY(8px);
    opacity: 0;
  }
  to {
    transform: translateY(0);
    opacity: 1;
  }
}

@keyframes sidebar-in {
  from {
    transform: translateX(100%);
    opacity: 0;
  }
  to {
    transform: translateX(0);
    opacity: 1;
  }
}

.animate-fade-up {
  animation: fade-up 0.35s ease both;
}
